import {createStoneWorld} from './stone-world.js';
import {createStoneGame,startStoneGame,pressStoneKey,tickStoneGame,setStonePaused,snapshotStone,restoreStone,STONE_STORAGE_KEY} from './stone-game.js';
import {createFeedback,isControlActivation} from './feedback.js';
const $=id=>document.getElementById(id),label=k=>k==='Space'?'空格':k==='Backspace'?'退格':k;
let storage,state=createStoneGame(),world,persistent=true,conflict=false,raf,previous=performance.now(),lastSave=0;
try{storage=localStorage;const raw=storage.getItem(STONE_STORAGE_KEY);if(raw)state=restoreStone(JSON.parse(raw))||state;}catch{persistent=false;}
setStonePaused(state,!['ready','complete'].includes(state.phase));
try{world=createStoneWorld($('world'));}catch(error){console.error(error);$('error').hidden=false;}
const feedback=createFeedback(value=>{$('feedback').classList.toggle('visible',!!value);for(const el of document.querySelectorAll('[data-key]'))el.classList.toggle('wrong',value?.pressed===el.dataset.key);if(value){$('wrongKey').textContent=label(value.pressed);$('wrongText').textContent=`按到了 ${label(value.pressed)}，试试${value.target==='F'?'左':'右'}手食指 ${value.target}`;}});
function save(){if(conflict)return;try{if(!storage)throw Error();storage.setItem(STONE_STORAGE_KEY,JSON.stringify(snapshotStone(state)));persistent=true;}catch{persistent=false;}$('saveNote').textContent=persistent?'本机自动保存 · 请使用实体键盘和英文输入法':'暂时无法保存，请保持页面打开 · 实体键盘练习';}
function announce(){ $('announce').textContent=state.target?`下一块石头 ${state.target}，${state.target==='F'?'左':'右'}手食指`:'已经走过八块石头，小熊去对岸野餐'; }
function render(){const ready=state.phase==='ready',done=state.phase==='complete',moving=['hopping','arriving'].includes(state.phase);$('count').textContent=state.index;$('start').hidden=!ready;$('pause').hidden=ready||done;$('done').hidden=!done;$('paused').hidden=!state.paused||ready||done;for(const el of document.querySelectorAll('[data-key]'))el.classList.toggle('active',el.dataset.key===state.target);$('finger').textContent=done?'到达啦，手指放松一下':state.target?`${state.target==='F'?'左':'右'}手食指按 ${state.target}`:'小熊正走向野餐垫';$('instruction').textContent=moving?'看，小熊正在稳稳落脚':done?'谢谢你，陪小熊一步步到了对岸':'看下一块石头，按对字母向前跳一步';$('gentleTitle').textContent=moving?'轻轻跳，稳稳落':done?'每一步都算数':'慢慢跳，也能到达';$('gentleText').textContent=moving?'落稳以后，再看下一块石头':done?'可以再玩一次，或回地图选别的关卡':'石头不会沉下去，准备好了再按';}
function start(){if(!world||conflict)return;feedback.clear();startStoneGame(state);render();announce();save();$('start').blur();}
function pause(){if(!world||state.paused||['ready','complete'].includes(state.phase))return;feedback.clear();setStonePaused(state,true);render();save();$('resume').focus({preventScroll:true});}
function resume(){if(conflict)return;feedback.clear();setStonePaused(state,false);render();announce();save();$('resume').blur();}
$('start').onclick=start;$('pause').onclick=pause;$('resume').onclick=resume;$('replay').onclick=()=>{feedback.clear();state=createStoneGame();render();save();$('start').focus({preventScroll:true});};
window.addEventListener('keydown',e=>{const modal=!$('paused').hidden?$('paused'):!$('done').hidden?$('done'):null;if(modal){if(e.key==='Tab'){const items=[...modal.querySelectorAll('button,a')],first=items[0],last=items.at(-1);if(!items.includes(document.activeElement)||(!e.shiftKey&&document.activeElement===last)){e.preventDefault();first.focus();}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}}return;}if(!world||conflict||e.ctrlKey||e.altKey||e.metaKey||e.shiftKey||e.repeat)return;if(e.isComposing||e.keyCode===229||e.which===229){$('instruction').textContent='请切换到英文输入法，再按石头上的字母';return;}if(e.key==='Escape'){pause();return;}if(isControlActivation(e,document.activeElement))return;if(e.key==='Enter'&&state.phase==='ready'){e.preventDefault();start();return;}const result=pressStoneKey(state,e);if(result.kind==='correct'){e.preventDefault();feedback.clear();render();save();}else if(result.kind==='wrong'){e.preventDefault();feedback.wrong(result.pressed,result.target);save();}});
window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('storage',e=>{if(e.storageArea!==storage||![STONE_STORAGE_KEY,null].includes(e.key))return;conflict=true;feedback.clear();setStonePaused(state,true);render();$('done').hidden=true;$('paused').hidden=false;$('pauseHeading').textContent='另一页面更新了过河进度';$('pauseText').textContent='为避免覆盖，请刷新后继续';$('resume').textContent='刷新并继续';$('resume').onclick=()=>location.reload();$('resume').focus();});
window.addEventListener('pagehide',()=>{save();feedback.clear();cancelAnimationFrame(raf);world?.dispose();});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
function frame(now){const dt=Math.max(0,(now-previous)/1000);previous=now;if(tickStoneGame(state,dt)){render();announce();save();if(state.phase==='complete')$('replay').focus({preventScroll:true});}world?.render(state,dt);if(now-lastSave>1000&&!state.paused&&!['ready','complete'].includes(state.phase)){save();lastSave=now;}raf=requestAnimationFrame(frame);}
render();save();if(state.paused)$('resume').focus();else if(state.phase==='complete')$('replay').focus();else $('start').focus();raf=requestAnimationFrame(frame);
